exercises.starter_code:
WITH ventes AS (
  SELECT client_id, COUNT(*) AS nb FROM ventes WHERE client_id IS NOT NULL GROUP BY client_id
)
SELECT client_id, nb FROM ventes WHERE nb >= 2 ORDER BY client_id;

exercises.solution:
WITH par_client AS (
  SELECT client_id, COUNT(*) AS nb FROM ventes WHERE client_id IS NOT NULL GROUP BY client_id
)
SELECT client_id, nb FROM par_client WHERE nb >= 2 ORDER BY client_id;
